const page = $('GET /{page-id} (fan_count)').item.json;
const insightsResult = $input.first().json;
const insightsFailed = !!insightsResult.error && !insightsResult.data;
const dailyValues = (!insightsFailed && insightsResult.data && insightsResult.data[0] && insightsResult.data[0].values) || [];

const totalViews = dailyValues.reduce((sum, d) => sum + (d.value || 0), 0);

return [{
  json: {
    platform: 'facebook',
    account_id: page.id,
    account_name: page.name,
    followers_count: page.followers_count ?? page.fan_count ?? null,
    views_recent_30d: dailyValues.length ? totalViews : null,
    views_average: dailyValues.length ? Math.round(totalViews / dailyValues.length) : null,
    account_status: null
  }
}];
